import { createRouter, createWebHistory } from "vue-router";
import Home from '../components/Layout/MainWindow/Home';
import Profile from '../components/Layout/MainWindow/Profile';
import Register from '../components/Layout/MainWindow/Register';
import ContactUs from '../components/Layout/MainWindow/ContactUs';
import About from '../components/Layout/MainWindow/About';
import Recover from '../components/Layout/MainWindow/Recover';
import Administration from '../components/Layout/MainWindow/Administration';
import Finance from '../components/Layout/MainWindow/Finance';
import Categories from '../components/Layout/MainWindow/Names';
import Notice from '../components/Layout/MainWindow/Notice';
import Report from '../components/Layout/MainWindow/Report';
import Overview from '../components/Layout/MainWindow/Overview.vue';

export const router = createRouter({
  history: createWebHistory(),
  routes: [
    {
      path: '/accounting/',
      name: 'Home',
      component: Home
    },
    {
      path: '/accounting/profile',
      name: 'Profile',
      component: Profile
    },
    {
      path: '/accounting/register',
      name: 'Sign Up',
      component: Register
    },
    {
      path: '/accounting/contactus',
      name: 'Contact Us',
      component: ContactUs
    },
    {
      path: '/accounting/about',
      name: 'About',
      component: About
    },
    {
      path: '/accounting/recover',
      name: 'Recover Password',
      component: Recover
    },
    {
      path: '/accounting/administration',
      name: 'Administration',
      component: Administration
    },
    {
      path: '/accounting/finance',
      name: 'Finance',
      component: Finance
    },
    {
      path: '/accounting/categories',
      name: 'Categories',
      component: Categories
    },
    {
      path: '/accounting/notice',
      name: 'Notice',
      component: Notice
    },
    {
      path: '/accounting/report',
      name: 'Report',
      component: Report
    },
    {
      path: '/accounting/overview',
      name: 'Overview',
      component: Overview
    }
  ]
});
