<template>
  <div class="container body-content">
    <router-view />
  </div>
</template>

<script>
import jQuery from "jquery";
const $ = jQuery;
window.$ = $;

export default {
  name: "MainWindow",
  components: {
  },
  watch: {
    '$router.currentRoute.value.name' () {
      document.title = this.$router.currentRoute.value.name + " - Accounting";

      document.getElementById('alerts').innerHTML = '';

      scroll(0,0);
    }
  }
};
</script>