<template>
  <div class="navbar navbar-inverse navbar-fixed-top heade">
    <div class="container">
      <div class="navbar-header" id="LogoControl" :class="$store.state.token ? 'logo-control-container' : ''">
        <button id="Toggle" type="button" class="navbar-toggle" data-toggle="collapse" data-target=".navbar-collapse" v-if="$store.state.token" onclick="this.classList.toggle('change');">
          <span class="icon-bar bar1"></span>
          <span class="icon-bar bar2"></span>
          <span class="icon-bar bar3"></span>
        </button>
        <a class="navbar-brand link" :class="$store.state.token ? 'logo-control-a' : ''" id="Logo" @click="openPage('/')" onclick="if(innerWidth <= 800 && $('#Toggle').hasClass('change')) document.getElementById('Toggle').click()" style="font-size: px"><img :src="getImage()" height="20" style="display:inline-block; padding-right:8px"/>Accounting</a>
      </div>
      <div class="navbar-collapse collapse">
        <ul class="nav navbar-nav">
          <li><a id="ManageData" class="link" @click="openPage('Finance')" onclick="if(innerWidth <= 800) document.getElementById('Toggle').click()" v-if="$store.state.token && !$store.state.userIdentity.user.isAdmin">Finance</a></li>
          <li><a id="ManageNames" class="link" @click="openPage('Categories')" onclick="if(innerWidth <= 800) document.getElementById('Toggle').click()" v-if="$store.state.token && !$store.state.userIdentity.user.isAdmin">Categories</a></li>
          <li><a id="Overview" class="link" @click="openPage('Overview')" onclick="if(innerWidth <= 800) document.getElementById('Toggle').click()" v-if="$store.state.token && !$store.state.userIdentity.user.isAdmin">Overview</a></li>
          <li><a id="Administration" class="link" @click="openPage('Administration')" onclick="if(innerWidth <= 800) document.getElementById('Toggle').click()" v-if="$store.state.token && $store.state.userIdentity.user.isAdmin">Administration</a></li>
        </ul>
        <ul class="nav navbar-nav navbar-right">
          <li class="nav-item dropdown">
            <a class="nav-link dropdown-toggle" id="navbardrop" data-toggle="dropdown" v-if="$store.state.token">
              <div v-if="$store.state.userIdentity.user">
                {{$store.state.userIdentity.user.username}}
              </div>
            </a>
            <div class="dropdown-menu">
              <a id="UserProfile" @click="openPage('Profile')" onclick="if(innerWidth <= 800) document.getElementById('Toggle').click()" class="dropdown-item">Profile</a>
              <a id="Logout" @click="logout()" onclick="if(innerWidth <= 800) document.getElementById('Toggle').click()" class="dropdown-item">Logout</a>
            </div>
          </li>
        </ul>
      </div>
    </div>
  </div>
</template>


<script>
import CommunicationHelpers from "../../helpers/CommunicationHelpers.js";
import jQuery from "jquery";
const $ = jQuery;
window.$ = $;

export default {
  name: "NaviGation",
  components: {
  },
  mounted() {
    $(document).on('click', function () {
      $('.collapse').removeClass('show');
    });
  },
  methods: {
    openPage(name) {
      this.$router.push('/accounting/'+name);
    },
    async logout() {
      this.$store.state.loading = true;

      await CommunicationHelpers.apiDataPost("/api/v1/user/Logout", this.$store.state);

      await this.$store.commit('resetStore', this.$store.state);

      this.passwordInput = document.getElementById("Password");
      
      if(this.passwordInput) {
        this.passwordInput.value = "";
      }
      
      this.$store.state.loading = false;
    },

    getImage() {
      return "data:image/x-icon;base64," + 
      "" +
      "" +
      "" +
      "" +
      "" +
      "" +
      "" +
      "" +
      "" +
      "" +
      "" +
      "" +
      "" +
      "";
    }
  }
};
</script>