<template>
  <div class="container">
    <div class="row">
      <h2>Overview</h2>
      <div class="col-xs-12 col-sm-4 col-md-3">
        <div class="block block-data" style="min-height: 0px!important" >
          <div class="filter">
            <p>
              <label for="NamesFilter">Categories</label>
              <multiselect id="NamesFilter" v-model="selectedNameFilter" :show-labels="false"
                :closeOnSelect="false" :options="names" :multiple="true" group-values="names" group-label="name" :group-select="true"
                placeholder="Select" track-by="id" label="name" openDirection="bottom" >
                <template #noResult>
                  <span>No categories found.</span>
                </template>
              </multiselect>
            </p>
            <p>
              <label for="DateFilter">Date</label>
              <VueDatePicker id="DateFilter" ref="datepicker" range v-model="calendarDate" :preset-dates="presetDates" :enable-time-picker="false" :text-input="textInputOptions" :format="format" />
            </p>
          </div>
        </div>
      </div>
      <div class="col-xs-12 col-sm-8 col-md-9">
        <div class="block block-data inner">
          <div class="inner">
            <ul class="nav nav-pills">
              <li class="active"><a id="homeButton" data-toggle="pill" href="#home">Balance</a></li>
              <li><a id="incomeChartsButton" data-toggle="pill" href="#incomeCharts">Income</a></li>
              <li><a id="expenseChartsButton" data-toggle="pill" href="#expenseCharts">Expense</a></li>
              <li><a id="monthlyBreakdownButton" data-toggle="pill" href="#monthlyBreakdown">Breakdown</a></li>
            </ul>

            <div class="tab-content">
              <div id="home" class="tab-pane fade in active">
                <div class="chartTitle">Balance</div>
                <VueApexChart id="balanceChart" type="area" ref="balanceChart" :options="getBalanceChartOptions()" :series="balanceSeries"></VueApexChart>
              </div>              
              <div id="incomeCharts" class="tab-pane fade incomeCharts">
                <div class="chartTitle">Income</div>
                <VueApexChart id="incomeChart" type="bar" ref="incomeChart" :options="getIncomeChartOptions()" :series="incomeSeries"></VueApexChart>
              </div>
              <div id="expenseCharts" class="tab-pane fade expenseCharts">
                <div class="chartTitle">Expense</div>
                <VueApexChart id="expenseChart" type="bar" ref="expenseChart" :options="getExpenseChartOptions()" :series="expenseSeries"></VueApexChart>
              </div>
              <div id="monthlyBreakdown" class="tab-pane fade">
                <div class="table-place">
                  <table v-if="this.getBreakdown().length == 0" class="table breakdown">
                    <div class="chartTitle">No data</div>
                  </table>
                  <table v-else v-for="(row, i) in this.getBreakdown()" :key="row.date" class="table breakdown">
                    <tbody>
                      <th colspan="3" :class="'breakdown-date breakdown-date'+i">
                        {{row.date}}
                      </th>
                    </tbody>
                    <tbody>
                      <tr v-for="(i) in row.data" :key="i.name">
                        <td class="breakdown-name">
                          {{i.name}}
                        </td>
                        <td class="breakdown-amount">
                          {{i.amount}}
                        </td>
                        <td class="breakdown-perc">
                          {{i.expensePerc ? '('+ i.expensePerc + '%)' : ''}}
                        </td>
                      </tr>
                      <tr>
                        <td colspan="3" class="breakdown-sum">
                          Month total: {{row.balance}}
                        </td>
                      </tr>
                    </tbody>
                  </table>
                </div>
              </div>
            </div>
          </div>
        </div>
      </div>
    </div>
  </div>
</template>

<script>
import CommunicationHelpers from '../../../helpers/CommunicationHelpers.js';
import jQuery from "jquery";
import Multiselect from 'vue-multiselect';
import VueDatePicker from '@vuepic/vue-datepicker';
import '@vuepic/vue-datepicker/dist/main.css';
import { endOfMonth, endOfYear, startOfMonth, startOfYear, subMonths, startOfDay, endOfDay, addDays } from 'date-fns';
import VueApexChart from 'vue3-apexcharts'
const $ = jQuery;
window.$ = $;

export default {
  name: "OverView",
  components: {
    Multiselect,
    VueDatePicker,
    VueApexChart
  },
  data() {
    return {
      finance: [],
      names: [],
      selectedName: null,
      selectedNameFilter: [],
      dateTimeFrom: null,
      dateTimeTo: null,
      calendarDate: null,
      presetDates: [
        { label: 'Today', value: [new Date(), new Date()] },
        { label: 'This month', value: [startOfMonth(new Date()), endOfMonth(new Date())] },
        {
          label: 'Last month',
          value: [startOfMonth(subMonths(new Date(), 1)), endOfMonth(subMonths(new Date(), 1))],
        },
        {
          label: 'Last 3 months',
          value: [startOfMonth(subMonths(new Date(), 3)), endOfMonth(subMonths(new Date(), 1))],
        },
        { label: 'This year', value: [startOfYear(new Date()), endOfYear(new Date())] },
      ],
      textInputOptions: {
        format: 'yyyy-MM-dd'
      },
      incomeSeries: [],
      expenseSeries: [],
      balanceSeries: [],
      innerWidth: null
    }
  },
  computed() {
    this.rmCheck = document.getElementById("RememberMe");
    this.usernameInput = document.getElementById("Username");

    if(this.rmCheck && this.usernameInput) {
        if (localStorage.checkbox && localStorage.checkbox !== "") {
            this.rmCheck.setAttribute("checked", "checked");
            this.usernameInput.value = localStorage.login;
            this.username = localStorage.login;
        } else {
            this.rmCheck.removeAttribute("checked");
            this.usernameInput.value = "";
        }
    }
  },
  async mounted() {
    this.$store.state.loading = true;

    if(localStorage.token && localStorage.login) {
        this.$store.state.token = localStorage.token;
        this.$store.state.accessToken = this.$store.state.token;
        this.$store.state.userIdentity.user.username = localStorage.login;

        this.$store.state.userIdentity.user = await CommunicationHelpers.apiDataPost("/api/v1/user/GetInfo", this.$store.state);

        if(this.$store.state.userIdentity.user) {
          this.interval = await setInterval(await this.resetToken, 900000);
          localStorage.setItem("tokenSetTime", Date.now());

          await this.setup();
        }
    } else {
        await this.$store.commit('resetStore', this.$store.state);
    }

    this.$store.state.loading = false;
  },
  methods: {
    async setup() {
      this.names = await CommunicationHelpers.apiDataPost("/api/v1/finance/GetNames", this.$store.state);

      if(this.names.length == 0) {
        this.$router.push('/accounting/Categories');
      } else {
        this.selectedName = this.names[0]?.names[0] ?? this.names[0];
      }

      await this.getData();
    },
    format(date) {
      let toReturn = "";

      if (date[1]) {
        let offset = 1;

        if(date[1].toISOString().split('T')[0] == date[0].toISOString().split('T')[0]) {
          offset = 0;
        }

        this.$store.state.dateTimeFrom = addDays(date[0], offset).toISOString().split('T')[0];
        this.$store.state.dateTimeTo = date[1].toISOString().split('T')[0];
        toReturn = `${this.$store.state.dateTimeFrom}  -  ${this.$store.state.dateTimeTo}`;
      } else if(date[0]) {
        this.$store.state.dateTimeFrom = date[0].toISOString().split('T')[0];
        this.$store.state.dateTimeTo = this.$store.state.dateTimeFrom;
        toReturn = this.$store.state.dateTimeFrom;
      }
      
      return toReturn;
    },
    async getData() {
      this.$store.state.loading = true;
      
      this.finance = (await CommunicationHelpers.apiDataPost('/api/v1/finance/GetFinances', this.$store.state)).rows.sort(function(a,b){
        return new Date(b.date) - new Date(a.date);
      });
      this.incomeSeries = this.getIncomeSeries();
      this.expenseSeries = this.getExpenseSeries();
      this.balanceSeries = this.getBalanceSeries();

      this.$store.state.loading = false;
    },
    getDateRangeInMonths(data) {
      let dates = []
      let minDate = 0;
      let maxDate = 0;

      if(data.length > 0){
        minDate = data[data.length - 1].date.slice(0,7);
        maxDate = data[0].date.slice(0,7);

        let maxYear = maxDate.slice(0,4);
        let maxMonth = maxDate.slice(5,7);
        
        let minYear = minDate.slice(0,4);
        let minMonth = minDate.slice(5,7);
        
        for(let i = minYear; i <= maxYear; i++) {
          for(let j = 1; j <= 12; j++) {
            if(minYear == maxYear){
              if(j >= minMonth && j <= maxMonth){
                dates.unshift(new Date(i,j,1).toISOString().slice(0,7));
              }
            } else {
                if(i == minYear && j >= minMonth) {
                dates.unshift(new Date(i,j,1).toISOString().slice(0,7));
              } else if(i == maxYear && j <= maxMonth) {
                dates.unshift(new Date(i,j,1).toISOString().slice(0,7));
              } else if (i != minYear && i != maxYear) {
                dates.unshift(new Date(i,j,1).toISOString().slice(0,7));
              }
            }
          }
        }
      }

      return dates;
    },
    getIncomeSeries() {
      let totalIncome = 0;

      let filteredFinance = this.finance.filter(item => {
          return (this.$store.state.nameIds.length == 0 || this.$store.state.nameIds.includes(item.name.id)) &&
            (item.type.factor > 0) &&
            (this.$store.state.dateTimeFrom ? new Date(item.date) >= new Date(this.$store.state.dateTimeFrom) && new Date(item.date) <= endOfDay(new Date(this.$store.state.dateTimeTo)) : true);
        });
      
      let dates = this.getDateRangeInMonths(filteredFinance);

      let groups = filteredFinance.reduce((group, item) => {
          let name = item.name.name;
          
          if (!group[name]) {
            group[name] = [];
          }
          totalIncome += item.amount;

          group[name].push(item);
        
        return group;
      }, {});

      filteredFinance = [];
      for(let key in groups) {
        let monthIncome = 0;
        let incomeGroups = groups[key].reduce((group, item) => {
          let date = item.date.slice(0,7);
          
          if (!group[date]) {
            group[date] = [];
          }
          monthIncome += item.amount;
          group[date].push(item);
          
          return group;
        }, {});

        let data = [] 
        
        for(let i = 0; i < dates.length; i++) {
          let incomeFactor = 0;

          if(incomeGroups[dates[i]]) {
            for(let j = 0; j < incomeGroups[dates[i]].length; j++) {
              incomeFactor += incomeGroups[dates[i]][j].amount;
            }
          }

          data.push({x: dates[i], y: parseFloat(incomeFactor.toFixed(2))});
        }

        filteredFinance.push({name: parseFloat((monthIncome/totalIncome*100).toFixed(2)) + '% - '+ key, data: data, perc: parseFloat((monthIncome/totalIncome*100).toFixed(2))})
      }
      
      return filteredFinance.sort(function(a,b){
          return b.perc - a.perc;
        });
    },
    getIncomeChartOptions() {
      return {
        chart: {
          fontFamily: 'inherit',
          type: 'bar',
          height: 440,
          zoom: {
            enabled: false
          }
        },
        noData: {
          text: "No data"
        },
        plotOptions: {
          bar: {
            horizontal: false,
            columnWidth: '55%',
            borderRadius: 2,
            borderRadiusApplication: 'end'
          },
        },
        dataLabels: {
          enabled: false
        },
        stroke: {
          show: true,
          width: 2,
          colors: ['transparent']
        },
        xaxis: {
          type: 'datetime',
        },
        fill: {
          opacity: 1
        },
        legend: {
          position: 'bottom'
        },
        tooltip: {
          x: {
            format: "yy-MM"
          },
          y: {
            formatter: function (val) {
              return val
            }
          }
        }
      };
    },
    getExpenseSeries() {
      let totalExpense = 0;

      let filteredFinance = this.finance.filter(item => {
          return (this.$store.state.nameIds.length == 0 || this.$store.state.nameIds.includes(item.name.id)) &&
            (item.type.factor < 0) &&
            (this.$store.state.dateTimeFrom ? new Date(item.date) >= startOfDay(new Date(this.$store.state.dateTimeFrom)) && new Date(item.date) <= endOfDay(new Date(this.$store.state.dateTimeTo)) : true);
        });
      
      let dates = this.getDateRangeInMonths(filteredFinance);

      let groups = filteredFinance.reduce((group, item) => {
          let name = item.name.name;
          
          if (!group[name]) {
            group[name] = [];
          }
          totalExpense += item.amount;

          group[name].push(item);
        
        return group;
      }, {});

      filteredFinance = [];
      for(let key in groups) {
        let monthExpense = 0;
        let expenseGroups = groups[key].reduce((group, item) => {
          let date = item.date.slice(0,7);
          
          if (!group[date]) {
            group[date] = [];
          }
          monthExpense += item.amount;
          group[date].push(item);
          
          return group;
        }, {});

        let data = [] 
        
        for(let i = 0; i < dates.length; i++) {
          let expenseFactor = 0;

          if(expenseGroups[dates[i]]) {
            for(let j = 0; j < expenseGroups[dates[i]].length; j++) {
              expenseFactor += expenseGroups[dates[i]][j].amount;
            }
          }

          data.push({x: dates[i], y: -parseFloat(expenseFactor.toFixed(2))});
        }

        filteredFinance.push({name: parseFloat((monthExpense/totalExpense*100).toFixed(2)) + '% - '+ key, data: data, perc: parseFloat((monthExpense/totalExpense*100).toFixed(2))})
      }
      
      return filteredFinance.sort(function(a,b){
          return b.perc - a.perc;
        });
    },
    getExpenseChartOptions() {
      return {
        chart: {
          fontFamily: 'inherit',
          type: 'bar',
          height: 440,
          zoom: {
            enabled: false
          }
        },
        noData: {
          text: "No data"
        },
        plotOptions: {
          bar: {
            horizontal: false,
            columnWidth: '55%',
            borderRadius: 2,
            borderRadiusApplication: 'end'
          },
        },
        dataLabels: {
          enabled: false
        },
        stroke: {
          show: true,
          width: 2,
          colors: ['transparent']
        },
        xaxis: {
          type: 'datetime',
        },
        fill: {
          opacity: 1
        },
        legend: {
          position: 'bottom'
        },
        tooltip: {
          x: {
            format: "yy-MM"
          },
          y: {
            formatter: function (val) {
              return val
            }
          }
        }
      };
    },
    getBalanceSeries() {
      let income = [];
      let expense = [];
      let balance = [];
      let total = [];
      
      let filteredFinance = this.finance.filter(item => {
          return (this.$store.state.nameIds.length == 0 || this.$store.state.nameIds.includes(item.name.id)) &&
            (this.$store.state.dateTimeFrom ? new Date(item.date) >= startOfDay(new Date(this.$store.state.dateTimeFrom)) && new Date(item.date) <= endOfDay(new Date(this.$store.state.dateTimeTo)) : true);
        });
      
      let dates = this.getDateRangeInMonths(filteredFinance);

      let groups = filteredFinance.filter(item => {
        return (this.$store.state.nameIds.length == 0 || this.$store.state.nameIds.includes(item.name.id)) &&
          (this.$store.state.dateTimeFrom ? new Date(item.date) >= startOfDay(new Date(this.$store.state.dateTimeFrom)) && new Date(item.date) <= endOfDay(new Date(this.$store.state.dateTimeTo)) : true);
      }).reduce((group, item) => {
        let date = item.date.slice(0,7);
        
        if (!group[date]) {
          group[date] = [];
        }
        
        group[date].push(item);
        
        return group;
      }, {});
      
      let finance = [];
      
      for(let key in groups) {
        let incomeFactor = 0;
        let expenseFactor = 0;
        
        for(let i = 0; i < groups[key].length; i++) {
          if(groups[key][i].type.factor > 0) {
            incomeFactor += groups[key][i].amount;
          } else {
            expenseFactor += groups[key][i].amount;
          }
        }
        
        finance.push({date: key, amount: incomeFactor, type: {factor: 1}});
        finance.push({date: key, amount: expenseFactor, type: {factor: -1}});
        balance.push({x: key, y: parseFloat((incomeFactor-expenseFactor).toFixed(2))});
      }
      
      for(let i = 0; i < finance.length; i++) {
        if (finance[i].type.factor > 0) {
          income.push({x: finance[i].date, y: parseFloat((finance[i].amount * finance[i].type.factor).toFixed(2))});
        } else {
          expense.push({x: finance[i].date, y: parseFloat((finance[i].amount * finance[i].type.factor).toFixed(2))});
        }
      }

      let unfilteredFinanceGroups = this.finance.reduce((group, item) => {
        let date = item.date.slice(0,7);
        
        if (!group[date]) {
          group[date] = [];
        }
        
        group[date].push(item);
        
        return group;
      }, {});

      let unfilteredBalance = [];
      for(let key in unfilteredFinanceGroups) {
        let incomeFactor = 0;
        let expenseFactor = 0;
        
        for(let i = 0; i < unfilteredFinanceGroups[key].length; i++) {
          if(unfilteredFinanceGroups[key][i].type.factor > 0) {
            incomeFactor += unfilteredFinanceGroups[key][i].amount;
          } else {
            expenseFactor += unfilteredFinanceGroups[key][i].amount;
          }
        }
        
        unfilteredBalance.push({x: key, y: incomeFactor-expenseFactor});
      }

      let totalSum = 0;
      for(let i = unfilteredBalance.length-1; i >= 0; i--) {
        totalSum += unfilteredBalance[i].y;
        if(dates.includes(unfilteredBalance[i].x)) {
          total.push({x: unfilteredBalance[i].x, y: parseFloat(totalSum.toFixed(2))});
        }
      }

      return [{
        name: 'Total',
        data: total
      },{
        name: 'Income',
        data: income
      },{
        name: 'Balance',
        data: balance
      },{
        name: 'Expense',
        data: expense
      }];
    },
    getBalanceChartOptions() {
      return {
        chart: {
          fontFamily: 'inherit',
          type: 'area',
          stacked: false,
          height: 440,
          zoom: {
            type: 'x',
            enabled: true,
            autoScaleYaxis: true
          },
          toolbar: {
            autoSelected: 'zoom'
          }
        },
        noData: {
          text: "No data"
        },
        dataLabels: {
          enabled: false
        },
        markers: {
          size: 0,
        },
        fill: {
          type: 'gradient',
          gradient: {
            shadeIntensity: 1,
            inverseColors: false,
            opacityFrom: 0.5,
            opacityTo: 0,
            stops: [0, 90, 100]
          },
        },
        legend: {
          position: 'bottom'
        },
        yaxis: {
          labels: {
            formatter: function (val) {
              return val;
            },
          }
        },
        xaxis: {
          type: 'datetime'
        },
        tooltip: {
          shared: false,
          x: {
            format: "yy-MM"
          },
          y: {
            formatter: function (val) {
              return val;
            }
          }
        }
      };
    },
    getBreakdown() {
      let groups = this.finance.filter(item => {
          return (this.$store.state.nameIds.length == 0 || this.$store.state.nameIds.includes(item.name.id)) &&
            (this.$store.state.dateTimeFrom ? new Date(item.date) >= startOfDay(new Date(this.$store.state.dateTimeFrom)) && new Date(item.date) <= endOfDay(new Date(this.$store.state.dateTimeTo)) : true);
        }).reduce((group, item) => {
          let date = item.date.slice(0,7);
          
          if (!group[date]) {
            group[date] = [];
          }
          
          group[date].push(item);
        
        return group;
      }, {});

      let finance = [];

      for(let key in groups) {
        let breakdownGroups = groups[key].reduce((group, item) => {
          let name = item.name.name;
          
          if (!group[name]) {
            group[name] = [];
          }
          
          group[name].push(item);
          
          return group;
        }, {});

        let data = [] 
        let incomeSum = 0;
        let balanceSum = 0;
        for(let breakdownKey in breakdownGroups) {
          let factor = 0;

          for(let i = 0; i < breakdownGroups[breakdownKey].length; i++) {
            factor += breakdownGroups[breakdownKey][i].amount*breakdownGroups[breakdownKey][i].type.factor;
          }

          incomeSum += factor > 0 ? factor : 0;
          balanceSum += factor;
          data.push({name: breakdownKey, amount: parseFloat(factor).toFixed(2)});
        }

        finance.push({date: key, data: data, income: parseFloat(incomeSum).toFixed(2), balance: parseFloat(balanceSum).toFixed(2)})
      }

      for(let i = 0; i < finance.length; i++) {
        for(let j = 0; j < finance[i].data.sort(function(a,b){
            return (b.amount) - (a.amount);
          }).length; j++) {
          if (finance[i].data[j].amount < 0){
            finance[i].data[j].expensePerc = finance[i].income != 0 ? parseFloat((finance[i].data[j].amount / finance[i].income * -100)).toFixed(2) : '-';
          }
        }
      }

      return finance;
    }
  },
  watch: {
    selectedNameFilter: async function() {
      this.$store.state.nameIds = this.selectedNameFilter.map(function(i) { return i.id });

      await this.getData();
    },
    calendarDate: async function() {
      if (this.calendarDate && this.calendarDate[1]) {
        let offset = 1;

        if(this.calendarDate[1].toISOString().split('T')[0] == this.calendarDate[0].toISOString().split('T')[0]) {
          offset = 0;
        }

        this.$store.state.dateTimeFrom = addDays(this.calendarDate[0], offset).toISOString().split('T')[0];
        this.$store.state.dateTimeTo = this.calendarDate[1].toISOString().split('T')[0];
      } else if(this.calendarDate && this.calendarDate[0]) {
        this.$store.state.dateTimeFrom = this.calendarDate[0].toISOString().split('T')[0];
        this.$store.state.dateTimeTo = this.$store.state.dateTimeFrom;
      } else {
        this.$store.state.dateTimeFrom = null;
        this.$store.state.dateTimeTo = null;
      }

      await this.getData();
    }
  },
  beforeRouteLeave(to, from, next) {
    this.$store.state.dateTimeFrom = null;
    this.$store.state.dateTimeTo = null;
    this.$store.state.nameIds = [];
    next();
  }
};
</script>
<style src="vue-multiselect/dist/vue-multiselect.min.css"></style>