import { createApp } from "vue";
import { createStore } from "vuex";
import { router } from "./router/index.js";
import App from "./App.vue";
import UserIdentity from "./models/UserIdentity";
import Dataset from "./models/Dataset.js";
import MvvMName from "./models/MvvMName.js";
import MvvMFinance from "./models/MvvMFinance.js";

const store = createStore({
    state: {
      apiUrl: process.env.VUE_APP_BACKEND_HOST,
      loading: false,
      userIdentity: new UserIdentity(),
      dataset: new Dataset(),
      names: new MvvMName(),
      finances: new MvvMFinance(),
      accessToken: null,
      token: null,
      searchString: "",
      data: [],
      oldData: [],
      rowCount: 0,
      from: 0,
      take: 0,
      typeId: null,
      nameIds: [],
      dateTimeFrom: null,
      dateTimeTo: null,
      isWide: false
    },
    mutations: {
      resetStore(state) {
        state.loading = true;
        state.userIdentity = new UserIdentity();
        state.accessToken = null;
        state.token = null;
        state.searchString = "";
        
        localStorage.removeItem("token");
        localStorage.removeItem("login");
        
        clearInterval();

        if(location.pathname != "/accounting/") {
          location.href = "/accounting/";
        }
        state.loading = false;
      }
    }
  });

let tokenSetTime = localStorage.getItem("tokenSetTime");
const timeout = 900000;

if(tokenSetTime && (Date.now() - tokenSetTime > timeout)) {
  store.commit('resetStore', store.state);
}

const app = createApp(App);

app.use(store);
app.use(router);

app.mount('#darken');