<template>
    <div class="container">
        <div class="row">
            <h2>{{this.$router.currentRoute.value.name}}</h2>
            <div class="col-xs-12 col-sm-6">
                <div class="block block-scaf block-data">
                    <div v-if="!$store.state.userIdentity.user.isAdmin">
                        <label for="GenerateButton">Select range of report</label>
                        <br />
                        <div class="range form-text-valid">
                            <VueDatePicker v-model="calendarDate" range :preset-dates="presetDates" :enable-time-picker="false" :text-input="textInputOptions" :format="format" />
                        </div>
                        <span class="tdspaced" style="color: red;" v-if="(!this.$store.state.dateTimeFrom || !this.$store.state.dateTimeTo) && triedGenerating">*</span>
                        <br />
                        <button id="GenerateButton" class="btn btn-primary profileBtn profile" Width="60%" @click="generateReport($event)">Generate Report</button>
                        <button id="CopyButton" class="btn btn-light profileBtn" @click="copyLink($event)" v-if="isWeb()">
                            <img src="clip.svg" width="20" alt="Copy" />
                        </button>
                        <div v-if="isWeb()">
                            <hr>
                            <label for="ExportButton">Export all user data to Excel</label>
                            <br />
                            <button id="ExportButton" class="btn btn-primary profile" Width="60%" @click="exportData()">Export</button>
                            <br />
                            <hr>
                            <label for="ImportButton">Import all user data from Excel</label>
                            <input id="ImportFile" type="file" class="form-control form-text-valid" @change="changeImportFile"/>
                            <span class="tdspaced" style="color: red;" v-if="triedImporting && !importFile">*</span>
                            <br />
                            <button id="ImportButton" class="btn btn-primary profileBtn profile" Width="60%" @click="importData($event)">Import</button>
                            <br />
                        </div>
                        <hr>
                    </div>

                    <label for="Email">New recovery email address</label>
                    <br />
                    <input id="Email" class="form-control form-text-valid" autocomplete="new-password" maxlength="100" v-on:keyup.enter="changeEmail($event)" v-model="email" />
                    <span class="tdspaced" style="color: red;" v-if="triedChangingEmail && !email.trim()">*</span>
                    <button id="ChangeEmailButton" class="btn btn-primary profileBtn profile" Width="60%" @click="changeEmail($event)">Change Email</button>
                    <span style="color: red; display: block; padding-top: 20px" v-if="!validateEmail(email) && email.trim()">Invalid format</span>
                    <br v-if="validateEmail(email) || !email.trim()" />

                    <div v-if="!$store.state.userIdentity.user.isAdmin">
                        <hr>
                        <label for="DeletePassword">To delete this account write in your password</label>
                        <br />
                        <input type="password" id="DeletePassword" autocomplete="new-password" class="form-control form-text-valid" maxlength="50" v-on:keyup.enter="deleteAccount($event)" v-model="deletePassword" />
                        <span class="tdspaced" style="color: red;" v-if="triedDeleting && !deletePassword.trim()">*</span>
                        <br />
                        <button id="DeleteUser" class="btn btn-primary profileBtn profile" Width="60%" @click="deleteAccount($event)">Delete</button>
                        <br />
                        <br />
                        <span id="failureText" style="color: red; width:100%; display:block" v-if="triedDeleting">Please try again</span>
                    </div>
                </div>
            </div>
            <div class="col-xs-12 col-sm-6">
                <div class="block block-scaf">
                    <label for="Password">Password</label>
                    <br />
                    <input type="password" id="Password" autocomplete="new-password" class="form-control form-text-valid" maxlength="50" v-on:keyup.enter="focus('NewPassword')" v-model="password" />
                    <span class="tdspaced" style="color: red;" v-if="triedChangingPassword && !password.trim()">*</span>
                    <br />
                    <br />
                    <label for="NewPassword">New Password</label>
                    <br />
                    <input type="password" id="NewPassword" autocomplete="new-password" class="form-control form-text-valid" maxlength="50" v-on:keyup.enter="focus('ConfirmNewPassword')" v-model="newPassword" />
                    <span class="tdspaced" style="color: red;" v-if="triedChangingPassword && !newPassword.trim()">*</span>
                    <br />
                    <br />
                    <label for="ConfirmNewPassword">Confirm New Password</label>
                    <br />
                    <input type="password" id="ConfirmNewPassword" autocomplete="new-password" class="form-control form-text-valid" maxlength="50" v-on:keyup.enter="changePassword($event)" v-model="confirmNewPassword" />
                    <span class="tdspaced" style="color: red;" v-if="triedChangingPassword && !confirmNewPassword.trim()">*</span>
                    <br />
                    <button id="ChangePasswordButton" class="btn btn-primary profileBtn profile" Width="60%" @click="changePassword($event)">Change Password</button>
                    <br />
                    <br />
                    <span id="failureText" style="color: red; width:100%; display:block" v-if="triedChangingPassword">Please try again</span>
                </div>
            </div>
        </div>
    </div>
</template>

<script>
import CommunicationHelpers from "../../../helpers/CommunicationHelpers.js";
import UserIdentity from "../../../models/UserIdentity.js";
import { Capacitor } from '@capacitor/core';
import { FileOpener } from '@capacitor-community/file-opener';
import write_blob from 'capacitor-blob-writer';
import { Directory } from '@capacitor/filesystem';
import VueDatePicker from '@vuepic/vue-datepicker';
import '@vuepic/vue-datepicker/dist/main.css';
import { endOfMonth, endOfYear, startOfMonth, startOfYear, subMonths, addDays } from 'date-fns';

export default {
  name: "ProFile",
  components: {
    VueDatePicker
  },
  data() {
    return {
        email: "",
        deletePassword: "",
        password: "",
        newPassword: "",
        confirmNewPassword: "",
        interval: null,
        triedChangingEmail: false,
        triedDeleting: false,
        triedChangingPassword: false,
        triedGenerating: false,
        triedImporting: false,
        calendarDate: null,
        importFile: null,
        presetDates: [
            { label: 'Today', value: [new Date(), new Date()] },
            { label: 'This month', value: [startOfMonth(new Date()), endOfMonth(new Date())] },
            {
            label: 'Last month',
            value: [startOfMonth(subMonths(new Date(), 1)), endOfMonth(subMonths(new Date(), 1))],
            },
            {
            label: 'Last 3 months',
            value: [startOfMonth(subMonths(new Date(), 3)), endOfMonth(subMonths(new Date(), 1))],
            },
            { label: 'This year', value: [startOfYear(new Date()), endOfYear(new Date())] },
        ],
        textInputOptions: {
            format: 'yyyy-MM-dd'
        }
    }
  },

  async mounted() {
    this.$store.state.loading = true;

    if(localStorage.token && localStorage.login) {
        this.$store.state.token = localStorage.token;
        this.$store.state.accessToken = this.$store.state.token;
        this.$store.state.userIdentity.user.username = localStorage.login;

        this.$store.state.userIdentity.user = await CommunicationHelpers.apiDataPost("/api/v1/user/GetInfo", this.$store.state);

        if(this.$store.state.userIdentity.user) {
          this.interval = await setInterval(await this.resetToken, 900000);
          localStorage.setItem("tokenSetTime", Date.now());
        }
    } else {
        await this.$store.commit('resetStore', this.$store.state);
    }

    this.$store.state.loading = false;
  },
  methods: {
    validateEmail(value) {
        return CommunicationHelpers.validateEmail(value);
    },
    focus(id) {
        document.getElementById(id).focus();
    },
    isWeb() {
        return Capacitor.getPlatform() == 'web';
    },
    format(date) {
        let toReturn = "";

        if (date[1]) {
        let offset = 1;

        if(date[1].toISOString().split('T')[0] == date[0].toISOString().split('T')[0]) {
            offset = 0;
        }

        this.$store.state.dateTimeFrom = addDays(date[0], offset).toISOString().split('T')[0];
        this.$store.state.dateTimeTo = date[1].toISOString().split('T')[0];
        toReturn = `${this.$store.state.dateTimeFrom}  -  ${this.$store.state.dateTimeTo}`;
        } else if(date[0]) {
        this.$store.state.dateTimeFrom = date[0].toISOString().split('T')[0];
        this.$store.state.dateTimeTo = this.$store.state.dateTimeFrom;
        toReturn = this.$store.state.dateTimeFrom;
        }

        return toReturn;
    },
    async resetToken() {
        this.$store.state.loading = true;

        await CommunicationHelpers.apiDataPost("/api/v1/user/Logout", this.$store.state);

        await this.$store.commit('resetStore', this.$store.state);

        this.$store.state.loading = false;
    },
    async changeEmail(event) {
        this.triedChangingEmail = true;

        if(!this.email.trim() || !this.validateEmail(this.email.trim())) {
            event.preventDefault();
        } else {
            this.$store.state.loading = true;

            this.triedChangingEmail = false;

            this.$store.state.userIdentity.user.recoveryEmail = this.email.trim();

            if(CommunicationHelpers.displaySuccessResponse(await CommunicationHelpers.apiDataPost("/api/v1/user/ChangeRecoveryEmail", this.$store.state))) {
                this.email = "";
            }

            this.$store.state.loading = false;
        }
    },
    async exportData() {
        this.$store.state.loading = true;

        let result = await CommunicationHelpers.apiDataPost("/api/v1/export/ExportAllData", this.$store.state);

        if(result) {
            var date = new Date();

            const link = document.createElement('a');
            link.href = 'data:application/octet-stream;charset=utf-8;base64,' + result;
            link.target = '_blank';
            link.download =
                this.$store.state.userIdentity.user.username + "_" +
                date.getFullYear() + "_" +
                ((date.getMonth() + 1).toString().length == 1 ? "0" + (date.getMonth() + 1) : (date.getMonth() + 1)) + "_" +
                date.getDate() + "_" +
                date.getHours() + "_" +
                date.getMinutes() + "_" +
                date.getSeconds() + '_data.xlsx';
            link.click();
        }
        else {
            CommunicationHelpers.displayAlerts({
                variants: ["info"],
                messages: ["No data"]
            });
        }

        this.$store.state.loading = false;
    },
    changeImportFile(event) {
        this.importFile = event.target.files[0] ?? null;
    },
    async importData(event) {
        this.triedImporting = true;

        this.$store.state.loading = true;

        if(!this.importFile) {
            event.preventDefault();
        } else {
            this.triedImporting = false;
            this.$store.state.loading = true;

            const formData = new FormData();
            formData.append('importFile', this.importFile);

            if(CommunicationHelpers.displaySuccessResponse(await CommunicationHelpers.apiImport("/api/v1/import/ImportAllData", formData, this.$store.state))) {
                this.importFile = null;
                document.getElementById('ImportFile').value = "";
            }
        }

    this.$store.state.loading = false;
    },
    async generateReport(event) {
        this.triedGenerating = true;

        this.$store.state.loading = true;

        if(!this.$store.state.dateTimeFrom || !this.$store.state.dateTimeTo) {
            event.preventDefault();
        } else {
            this.triedGenerating = false;

            if (!this.isWeb()) {
                let result = await CommunicationHelpers.apiDataPost("/api/v1/export/ExportReport", this.$store.state);

                if(result) {
                    var byteCharacters = atob(result);
                    var byteNumbers = new Array(byteCharacters.length);

                    for (var i = 0; i < byteCharacters.length; i++) {
                        byteNumbers[i] = byteCharacters.charCodeAt(i);
                    }

                    var byteArray = new Uint8Array(byteNumbers);
                    var file = new Blob([byteArray], { type: 'application/pdf;base64' });

                    let dateTimeFrom = new Date(this.$store.state.dateTimeFrom);
                    let dateTimeTo = new Date(this.$store.state.dateTimeTo);

                    await write_blob({
                        path: this.$store.state.userIdentity.user.username + "_" +
                                dateTimeFrom.getFullYear() + "-" +
                                ((dateTimeFrom.getMonth() + 1).toString().length == 1 ? "0" + (dateTimeFrom.getMonth() + 1) : (dateTimeFrom.getMonth() + 1)) + "-" +
                                dateTimeFrom.getDate() + "_" +
                                dateTimeTo.getFullYear() + "-" +
                                ((dateTimeTo.getMonth() + 1).toString().length == 1 ? "0" + (dateTimeTo.getMonth() + 1) : (dateTimeTo.getMonth() + 1)) + "-" +
                                dateTimeTo.getDate() + '_report.pdf',
                        directory: Directory.Cache,
                        blob: file,
                    }).then(async (savedFile) => {
                        await FileOpener.open({ filePath: savedFile });
                    });
                }
                else {
                    CommunicationHelpers.displayAlerts({
                        variants: ["info"],
                        messages: ["No data"]
                    });
                }
            } else {
                window.open('Report?from=' + this.$store.state.dateTimeFrom + '&to=' + this.$store.state.dateTimeTo/* + "&ac=true"*/, '_blank');
            }
        }

        this.$store.state.loading = false;
    },
    async copyLink(event) {
        this.triedGenerating = true;

        if(!this.$store.state.dateTimeFrom || !this.$store.state.dateTimeTo) {
            event.preventDefault();
        } else {
            this.triedGenerating = false;

            CommunicationHelpers.copyToClipboard(location.origin + '/Report?from=' + this.$store.state.dateTimeFrom + '&to=' + this.$store.state.dateTimeTo);
            alert("Link to " + this.$store.state.dateTimeFrom + " / " + this.$store.state.dateTimeTo + " report copied");
        }
    },
    async deleteAccount(event) {
        this.triedDeleting = true;

        if(!this.deletePassword.trim()) {
            event.preventDefault();
        } else {
            if(confirm("Are you sure you want to delete your user and all data?")) {
                this.$store.state.loading = true;

                this.$store.state.userIdentity = new UserIdentity();
                this.$store.state.userIdentity.user.username = localStorage.login;
                this.$store.state.accessToken = CommunicationHelpers.encodeStringToUtf8(localStorage.login + ":" + this.deletePassword.trim());

                this.$store.state.token = await CommunicationHelpers.apiDataPost("/api/v1/auth/login", this.$store.state);

                if (this.$store.state.token && !CommunicationHelpers.isEmpty(this.$store.state.token)) {
                    this.triedDeleting = false;

                    localStorage.token = this.$store.state.token;

                    this.$store.state.accessToken = this.$store.state.token;

                    if(CommunicationHelpers.displaySuccessResponse(await CommunicationHelpers.apiDataPost("/api/v1/user/DeleteAccount", this.$store.state))) {
                        this.deletePassword = "";
                    }

                    await setTimeout(() => {
                        this.$store.commit('resetStore', this.$store.state);
                    }, 3000);
                } else {
                    this.$store.state.token = localStorage.token;
                    this.deletePassword = "";
                }

                this.$store.state.loading = false;
            } else {
                this.triedDeleting = false;
                this.deletePassword = "";
            }
        }
    },
    async changePassword(event) {
        this.triedChangingPassword = true;

        if(!this.password.trim() || !this.newPassword.trim() || !this.confirmNewPassword.trim()) {
            event.preventDefault();
        } else {
            if(this.newPassword.trim() == this.confirmNewPassword.trim()) {
                if(this.newPassword.trim().length < 8) {
                    alert("Password must contain at least 8 symbols");
                    this.newPassword = "";
                    this.confirmNewPassword = "";
                } else {
                    this.$store.state.loading = true;

                    this.$store.state.userIdentity = new UserIdentity();
                    this.$store.state.userIdentity.user.username = localStorage.login;
                    this.$store.state.accessToken = CommunicationHelpers.encodeStringToUtf8(localStorage.login + ":" + this.password);

                    this.$store.state.token = await CommunicationHelpers.apiDataPost("/api/v1/auth/login", this.$store.state);

                    if (this.$store.state.token && !CommunicationHelpers.isEmpty(this.$store.state.token)) {
                        this.triedChangingPassword = false;
                        localStorage.token = this.$store.state.token;

                        this.$store.state.userIdentity.user.password = CommunicationHelpers.encodeStringToUtf8(localStorage.login + ":" + this.newPassword);

                        if(CommunicationHelpers.displaySuccessResponse(await CommunicationHelpers.apiDataPost("/api/v1/auth/ChangePassword", this.$store.state))) {
                            this.password = "";
                            this.newPassword = "";
                            this.confirmNewPassword = "";
                        }

                        this.interval = setInterval(await this.resetToken, 900000);
                        localStorage.setItem("tokenSetTime", Date.now());
                    } else {
                        this.$store.state.token = localStorage.token;
                        this.password = "";
                        this.newPassword = "";
                        this.confirmNewPassword = "";
                    }

                    this.$store.state.loading = false;
                }
            } else {
                alert("Passwords do not match");
                this.confirmNewPassword = "";
            }
        }
    }
  },
  watch: {
    calendarDate: async function() {
        if (this.calendarDate && this.calendarDate[1]) {
        let offset = 1;

        if(this.calendarDate[1].toISOString().split('T')[0] == this.calendarDate[0].toISOString().split('T')[0]) {
          offset = 0;
        }

        this.$store.state.dateTimeFrom = addDays(this.calendarDate[0], offset).toISOString().split('T')[0];
        this.$store.state.dateTimeTo = this.calendarDate[1].toISOString().split('T')[0];
      } else if(this.calendarDate && this.calendarDate[0]) {
        this.$store.state.dateTimeFrom = this.calendarDate[0].toISOString().split('T')[0];
        this.$store.state.dateTimeTo = this.$store.state.dateTimeFrom;
      } else {
        this.$store.state.dateTimeFrom = null;
        this.$store.state.dateTimeTo = null;
      }
    },
  },
  beforeRouteLeave(to, from, next) {
    this.$store.state.dateTimeFrom = null;
    this.$store.state.dateTimeTo = null;
    next();
  }
};
</script>