export default class MvvMName {
    constructor(dataRow) {
        if(dataRow) {
            this.id = dataRow.id;
            this.name = dataRow.name;
            this.parentId = dataRow.parentId;
            this.names = dataRow.names;
        } else {
            this.id = 0;
            this.name = null;
            this.parentId = null;
            this.names = [];
        }
    }
}

export function GetMvvMName(dataRow) {
    return new MvvMName(dataRow);
  }